import 'package:flutter/material.dart';
import '../../../core/models/post.dart';
import '../../../services/social/post_repository.dart';
class AurenCreatePostScreen extends StatefulWidget{const AurenCreatePostScreen({super.key});@override State<AurenCreatePostScreen> createState()=>_AurenCreatePostScreenState();}
class _AurenCreatePostScreenState extends State<AurenCreatePostScreen>{final c=TextEditingController();bool saving=false;Future<void> save()async{final t=c.text.trim();if(t.isEmpty)return;setState(()=>saving=true);try{await PostRepository().create(AurenPost(id:'post_${DateTime.now().microsecondsSinceEpoch}',authorId:'current-user',text:t,createdAt:DateTime.now()));if(mounted)Navigator.pop(context);}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create Pulse')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:c,maxLines:6,decoration:const InputDecoration(hintText:'What do you want to share?')),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:saving?null:save,child:Text(saving?'Publishing…':'Publish')))])));@override void dispose(){c.dispose();super.dispose();}}